<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import OnboardingOption from '../../components/onboarding/OnboardingOption.vue'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'
const router = useRouter(); const store = useCompanyOnboardingStore(); const error = ref(''); const options = [{ label: 'Somente eu', value: 'solo' }, { label: '2 a 5 pessoas', value: '2_5' }, { label: '6 a 10 pessoas', value: '6_10' }, { label: '11 a 20 pessoas', value: '11_20' }, { label: 'Mais de 20', value: '20_plus' }]
function next() { error.value = store.state.profile.companySize ? '' : 'Escolha o tamanho da sua operação.'; if (error.value) return; store.nextStep(); router.push('/cadastro/atendimento') }
</script>
<template><section><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Qual é o tamanho da sua operação?</h1><p class="mt-5 leading-7 text-neutral-600">Isso nos ajuda a preparar seu espaço de trabalho.</p><div class="mt-8 grid gap-3 sm:grid-cols-2"><OnboardingOption v-for="option in options" :key="option.value" :label="option.label" :value="option.value" :selected="store.state.profile.companySize === option.value" @select="store.updateProfile({ companySize: $event })" /></div><p v-if="error" class="mt-3 text-sm text-red-600">{{ error }}</p><BaseButton class="mt-8 min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" @click="next">Continuar</BaseButton></section></template>
